using System;using System.IO;using System.Linq;using System.Text;using System.Diagnostics;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Threading;
namespace TriReviewBridge {
 public partial class WorkbenchApp {
  string SoakProof,SoakAltProject,SoakAltWorkspace;Stopwatch SoakClock;DispatcherTimer SoakBeat,SoakActions;bool SoakBusy,SoakStopping;long SoakHeartbeats;double SoakLastBeat,SoakMaxGap;int SoakToggles,SoakSwitches,SoakSelections,SoakSkipped,SoakFailures;bool SoakDraftPreserved=true;Scope SoakFirstScope,SoakOtherScope;string SoakFirstText="虚构稳定性主空间草稿，不发送。",SoakOtherText="虚构稳定性第二空间草稿，不发送。";int SoakWarmup;double SoakNextToggle=30,SoakNextSwitch=60,SoakNextSelection=180;
  void WriteSoakProof(bool stopped=false,bool passed=false,string error=null){var proof=Json.D("format","TRB_NATIVE_SOAK_PROBE_V1","ready",true,"pid",Process.GetCurrentProcess().Id,"elapsedSeconds",SoakClock.Elapsed.TotalSeconds,"heartbeats",SoakHeartbeats,"maxHeartbeatGapMs",SoakMaxGap,"themeToggles",SoakToggles,"scopeSwitches",SoakSwitches,"pendingSelectionChecks",SoakSelections,"selectionChecksSkipped",SoakSkipped,"backendRefreshFailures",SoakFailures,"draftPreserved",SoakDraftPreserved,"stopped",stopped,"passed",passed,"error",error,"workspaceId",CurrentScope==null?null:CurrentScope.WorkspaceId,"preferencePath",UxThemePreferencePath,"draftStorage",DraftStore==null?null:DraftStore.FilePath,"realAgentOperations",0);string temp=SoakProof+".next";File.WriteAllText(temp,Json.Show(proof),new UTF8Encoding(false));if(File.Exists(SoakProof))File.Replace(temp,SoakProof,null);else File.Move(temp,SoakProof);}
  void CheckSoakDraft(){string expected=CurrentScope.WorkspaceId==SoakFirstScope.WorkspaceId?SoakFirstText:SoakOtherText;if(Composer.Text!=expected){SoakDraftPreserved=false;throw new Exception("Native stability draft changed or crossed workspace");}}
  async Task SoakSwitch(){CheckSoakDraft();var next=CurrentScope.WorkspaceId==SoakFirstScope.WorkspaceId?SoakOtherScope:SoakFirstScope;bool wasReadOnly=Composer.IsReadOnly;await Choose(next);if(Composer.Text==""&&next.WorkspaceId==SoakOtherScope.WorkspaceId)Composer.Text=SoakOtherText;Composer.IsReadOnly=wasReadOnly;CheckSoakDraft();SaveCurrentDraft();SoakSwitches++;}
  void SoakToggle(){CheckSoakDraft();var recipients=Chosen().ToArray();var reply=ReplyId;var workspace=CurrentScope.WorkspaceId;C<Button>("ThemeToggleButton").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));if(!Chosen().SequenceEqual(recipients)||ReplyId!=reply||CurrentScope.WorkspaceId!=workspace)throw new Exception("Theme toggle changed collaboration selection");CheckSoakDraft();SoakToggles++;}
  async Task<bool> SoakSelection(){if(!UxScopeMatches()||Refreshing||Items.ItemsSource==null||Messages.ItemsSource==null||Items.ItemsSource.Cast<ItemRow>().Count()==0||Messages.ItemsSource.Cast<MessageRow>().Select(m=>m.CaseId).Distinct().Count()<2){SoakSkipped++;return false;}CheckSoakDraft();await RunUxPendingRefreshRegression();CheckSoakDraft();SoakSelections++;return true;}
  async Task SoakActionTick(){if(SoakBusy||SoakStopping)return;SoakBusy=true;try{CheckSoakDraft();double elapsed=SoakClock.Elapsed.TotalSeconds;if(SoakWarmup<5&&elapsed>=2+SoakWarmup*2){if(SoakWarmup==0||SoakWarmup==2)SoakToggle();else if(SoakWarmup==1||SoakWarmup==3)await SoakSwitch();else if(!await SoakSelection())return;SoakWarmup++;}else if(elapsed>=SoakNextToggle){SoakToggle();SoakNextToggle+=30;}else if(elapsed>=SoakNextSwitch){await SoakSwitch();SoakNextSwitch+=60;}else if(elapsed>=SoakNextSelection){await SoakSelection();SoakNextSelection+=180;}if(UxConnectionFailed)SoakFailures++;}catch(Exception e){SoakStopping=true;SoakBeat.Stop();SoakActions.Stop();try{SaveCurrentDraft();WriteSoakProof(true,false,e.ToString());}finally{Environment.ExitCode=1;Win.Close();}}finally{SoakBusy=false;}}
  async Task RunSoakProbe(){string allowed=Path.GetFullPath(Path.Combine(Root,"test-output"))+Path.DirectorySeparatorChar;if(!Path.GetFullPath(SoakProof).StartsWith(allowed,StringComparison.OrdinalIgnoreCase))throw new Exception("Stability proof must stay in platform test-output");Directory.CreateDirectory(Path.GetDirectoryName(SoakProof));SoakFirstScope=CurrentScope;var project=Navigation.First(p=>Json.Str(p,"id")==SoakAltProject);var workspace=Json.Arr(Json.Get(project,"workspaces")).First(w=>Json.Str(w,"id")==SoakAltWorkspace);SoakOtherScope=new Scope(){ProjectId=SoakAltProject,ProjectName=Json.Str(project,"name"),WorkspaceId=SoakAltWorkspace,WorkspaceName=Json.Str(workspace,"name")};if(Composer.Text!="")throw new Exception("New stability window unexpectedly restored an existing draft");Composer.Text=SoakFirstText;Composer.IsReadOnly=true;Tree.IsEnabled=false;SaveCurrentDraft();Win.Title+=" · 虚构稳定性测试（不发送）";SoakClock=Stopwatch.StartNew();SoakBeat=new DispatcherTimer(){Interval=TimeSpan.FromSeconds(1)};SoakBeat.Tick+=(s,e)=>{double now=SoakClock.Elapsed.TotalMilliseconds;SoakMaxGap=Math.Max(SoakMaxGap,now-SoakLastBeat);SoakLastBeat=now;SoakHeartbeats++;if(SoakHeartbeats%5==0)WriteSoakProof();};SoakActions=new DispatcherTimer(){Interval=TimeSpan.FromSeconds(1)};SoakActions.Tick+=async(s,e)=>await SoakActionTick();SoakBeat.Start();SoakActions.Start();Timer.Start();WriteSoakProof();while(!SoakStopping&&!File.Exists(SoakProof+".stop"))await Task.Delay(250);if(SoakStopping)return;SoakStopping=true;SoakActions.Stop();while(SoakBusy)await Task.Delay(50);SoakBeat.Stop();Timer.Stop();CheckSoakDraft();SaveCurrentDraft();WriteSoakProof(true,true);Win.Close();}
 }
}
